// The ghost rival: a translucent Kestrel flying the par line beside you.
// It is generated by the same autopilot that stages screenshots, so the
// par time is honest, and your own best path replaces it once you beat it.
// The HUD delta turns every sortie into a race against a visible opponent.
import { STEP, clamp } from './config.js';
import { bearingTo, createFlightState, shortestAngle, stepFlight } from './flight.js';
import { RING_COURSE, runwayStartPose } from './missions.js';

const SAMPLE_EVERY = 0.5;

function autopilotControls(state, aim, targetSpeed) {
  const headingError = shortestAngle(bearingTo(state, aim) - state.heading);
  const altitudeError = aim.y - state.y;
  return {
    pitch: clamp(altitudeError * 0.006 - state.verticalSpeed * 0.03, -0.4, 0.4),
    roll: clamp(headingError * 1.1 - state.roll * 0.3, -1, 1),
    yaw: 0,
    throttle: clamp((targetSpeed - state.speed) * 0.08 + (state.throttle < 0.5 ? 0.4 : 0), -1, 1),
    brake: false,
  };
}

export function buildParGhost() {
  const state = createFlightState(runwayStartPose());
  state.onGround = false;
  state.y += 120;
  state.speed = 48;
  state.throttle = 0.75;
  state.gearDown = false;
  state.gearTransit = 1;
  const samples = [];
  let ringIndex = 0;
  let elapsed = 0;
  for (let step = 0; step < 60 * 260 && ringIndex < RING_COURSE.length; step += 1) {
    const ring = RING_COURSE[ringIndex];
    stepFlight(state, autopilotControls(state, ring, 54), STEP);
    elapsed += STEP;
    if (step % Math.round(SAMPLE_EVERY / STEP) === 0) {
      samples.push({ t: elapsed, x: state.x, y: state.y, z: state.z, heading: state.heading, pitch: state.pitch, roll: state.roll, speed: state.speed, ring: ringIndex });
    }
    const dx = ring.x - state.x;
    const dy = ring.y - state.y;
    const dz = ring.z - state.z;
    if (Math.sqrt(dx * dx + dy * dy + dz * dz) < 70) ringIndex += 1;
    if (state.onGround) break;
  }
  return { samples, label: 'PAR GHOST', totalTime: elapsed };
}

export function createGhostRecorder() {
  return {
    samples: [],
    timer: 0,
    record(state, elapsed, ringIndex) {
      this.timer += STEP;
      if (this.timer < SAMPLE_EVERY) return;
      this.timer = 0;
      this.samples.push({ t: elapsed, x: state.x, y: state.y, z: state.z, heading: state.heading, pitch: state.pitch, roll: state.roll, speed: state.speed, ring: ringIndex });
    },
  };
}

export function ghostPoseAt(ghost, elapsed) {
  if (!ghost || ghost.samples.length === 0) return null;
  const samples = ghost.samples;
  if (elapsed <= samples[0].t) return samples[0];
  for (let i = 1; i < samples.length; i += 1) {
    if (samples[i].t >= elapsed) {
      const a = samples[i - 1];
      const b = samples[i];
      const f = clamp((elapsed - a.t) / Math.max(b.t - a.t, 0.001), 0, 1);
      return {
        x: a.x + (b.x - a.x) * f,
        y: a.y + (b.y - a.y) * f,
        z: a.z + (b.z - a.z) * f,
        heading: a.heading + shortestAngle(b.heading - a.heading) * f,
        pitch: a.pitch + (b.pitch - a.pitch) * f,
        roll: a.roll + (b.roll - a.roll) * f,
        speed: a.speed + (b.speed - a.speed) * f,
        ring: b.ring,
      };
    }
  }
  return samples[samples.length - 1];
}

export function ghostDeltaSeconds(ghost, elapsed, ringsDone) {
  if (!ghost || ghost.samples.length === 0) return null;
  const ghostNow = ghostPoseAt(ghost, elapsed);
  if (!ghostNow) return null;
  const ringGap = (ghostNow.ring ?? 0) - ringsDone;
  const aheadSample = ghost.samples.find((sample) => sample.ring > ringsDone);
  const timeToNextRing = aheadSample ? Math.max(0, aheadSample.t - elapsed) : 0;
  if (ringGap > 0) return -(ringGap * 18 + timeToNextRing);
  if (ringGap < 0) return -ringGap * 18;
  return timeToNextRing > 0 ? timeToNextRing : 0;
}
